const $=s=>document.querySelector(s);let docs=[],current=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,6500)}
async function api(path,body){let r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let d=await r.json();if(!r.ok){let e=new Error(d.error);e.id=d.id;throw e}return d}
function view(v){['list','detail','rules'].forEach(k=>$('#'+k+'View').hidden=k!==v);$('#navDocs').classList.toggle('active',v!=='rules');$('#navRules').classList.toggle('active',v==='rules')}
function badge(s){return `<span class="badge ${s==='Согласован'?'green':s==='Возвращён'?'orange':''}">${esc(s)}</span>`}
function render(){let query=$('#search').value.toLowerCase(),status=$('#filter').value;let visible=docs.filter(d=>(!status||d.status===status)&&[d.fields.supplier,d.fields.number,d.filename].join(' ').toLowerCase().includes(query));$('#rows').innerHTML=visible.map(d=>`<tr><td><strong>${esc(d.fields.supplier||'Поставщик не определён')}</strong><small>Счёт ${esc(d.fields.number||'без номера')} · ${esc(d.fields.date||'без даты')}</small></td><td>${d.fields.amount?Number(d.fields.amount).toLocaleString('ru-RU',{style:'currency',currency:'RUB'}):'—'}</td><td>${badge(d.status)}</td><td>${esc(d.route)}</td><td><button class="textbtn" data-id="${d.id}">Открыть →</button></td></tr>`).join('');$('#empty').hidden=visible.length>0;$('#empty').innerHTML=docs.length?'Документы по запросу не найдены.':'Пока нет документов.<br><small>Загрузите счёт или откройте демонстрационный пример.</small>';$('#total').textContent=docs.length;$('#review').textContent=docs.filter(d=>['Проверка','Возвращён'].includes(d.status)).length;$('#pending').textContent=docs.filter(d=>d.status==='На согласовании').length;$('#approved').textContent=docs.filter(d=>d.status==='Согласован').length;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>guard(()=>openDoc(b.dataset.id)))}
async function refresh(){docs=await api('/api/documents');render()}
async function openDoc(id){current=await api('/api/documents/'+id);view('detail');$('#docTitle').textContent='Счёт '+(current.fields.number||'без номера');$('#docSubtitle').textContent=current.filename;$('#docStatus').textContent=current.status;let editable=['Проверка','Возвращён'].includes(current.status);for(let [k,v] of Object.entries(current.fields)){let el=$(`#fields [name="${k}"]`);el.value=v;el.disabled=!editable}$('#source').textContent=current.source;$('#editActions').hidden=!editable;$('#approvalActions').hidden=current.status!=='На согласовании';$('#closedNote').hidden=current.status!=='Согласован';$('#routeInfo').textContent='Согласующий: '+current.route+' · демонстрация роли';$('#reason').value='';$('#history').innerHTML=current.events.map(e=>`<li><small>${esc(e.time.replace('T',' '))}</small><br>${esc(e.message)}</li>`).join('')}
async function guard(fn){try{await fn()}catch(e){toast(e.message)}}
async function action(a){let fields=Object.fromEntries(new FormData($('#fields')));await api(`/api/documents/${current.id}/${a}`,{fields,reason:$('#reason').value});await openDoc(current.id);await refresh();toast(a==='submit'?'Документ отправлен на согласование.':'Изменения сохранены.')}
async function upload(name,data){try{let r=await api('/api/upload',{name,data});await refresh();await openDoc(r.id);toast('Документ загружен. Проверьте реквизиты.')}catch(e){if(e.id){await openDoc(e.id);toast('Этот пример уже есть в реестре.')}else throw e}}
$('#file').onchange=()=>guard(async()=>{let f=$('#file').files[0];if(!f)return;if(f.size>5000000)throw new Error('Максимальный размер — 5 МБ.');let data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(new Error('Не удалось прочитать файл'));r.readAsDataURL(f)});await upload(f.name,data);$('#file').value=''});
async function demo(big){let text=`СЧЁТ НА ОПЛАТУ № ${big?'205':'104'} от 09.11.2026\nПоставщик: ООО «${big?'Орбита':'Вектор'}»\nИНН: ${big?'7712345678':'7701234567'}\nИтого к оплате: ${big?'85 000,00':'24 500,00'} руб.\nДемонстрационные данные. Не является платёжным документом.\n`;let bytes=new TextEncoder().encode(text);await upload(big?'Счёт_205.txt':'Счёт_104.txt',btoa(String.fromCharCode(...bytes)))}
$('#demoSmall').onclick=()=>guard(()=>demo(false));$('#demoLarge').onclick=()=>guard(()=>demo(true));$('#back').onclick=$('#navDocs').onclick=()=>{view('list');guard(refresh)};$('#navRules').onclick=()=>guard(async()=>{view('rules');$('#threshold').value=(await api('/api/settings')).threshold});$('#saveRule').onclick=()=>guard(async()=>{await api('/api/settings',{threshold:$('#threshold').value});toast('Правило сохранено. Оно применяется при следующей отправке.')});['save','submit','approve','reject'].forEach(a=>$('#'+a).onclick=()=>guard(()=>action(a)));$('#fields').onsubmit=e=>e.preventDefault();$('#search').oninput=render;$('#filter').onchange=render;guard(refresh);
